import{_ as e,o as t,c as s,ae as i}from"./chunks/framework.C4zpkcTP.js";const k=JSON.parse('{"title":"AI Agent Skill","description":"Laravel Myanmar NRC is built for humans and AI agents. Install its agent skill so Claude Code, Codex, Cursor and other coding agents use the package correctly.","frontmatter":{"title":"AI Agent Skill","description":"Laravel Myanmar NRC is built for humans and AI agents. Install its agent skill so Claude Code, Codex, Cursor and other coding agents use the package correctly."},"headers":[],"relativePath":"laravel-myanmar-nrc/ai-agent-skill.md","filePath":"laravel-myanmar-nrc/ai-agent-skill.md"}'),r={name:"laravel-myanmar-nrc/ai-agent-skill.md"};function n(l,a,o,h,d,p){return t(),s("div",null,[...a[0]||(a[0]=[i('<h1 id="ai-agent-skill" tabindex="-1">AI Agent Skill <a class="header-anchor" href="#ai-agent-skill" aria-label="Permalink to &quot;AI Agent Skill&quot;">​</a></h1><p>Laravel Myanmar NRC is built for humans and AI agents. These docs are written for developers, and the package also ships an agent skill: a short guide that teaches coding agents such as Claude Code, Codex and Cursor how to install, configure and use Laravel Myanmar NRC the way it&#39;s meant to be used.</p><h2 id="with-laravel-boost" tabindex="-1">With Laravel Boost <a class="header-anchor" href="#with-laravel-boost" aria-label="Permalink to &quot;With Laravel Boost&quot;">​</a></h2><p>If your app uses <a href="https://github.com/laravel/boost" target="_blank" rel="noreferrer">Laravel Boost</a>, the skill is installed for you:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boost:install</span></span></code></pre></div><p>Already set up? Run <code>php artisan boost:update</code> after updating Laravel Myanmar NRC to refresh it.</p><h2 id="with-any-other-agent" tabindex="-1">With any other agent <a class="header-anchor" href="#with-any-other-agent" aria-label="Permalink to &quot;With any other agent&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> laranex/laravel-myanmar-nrc</span></span></code></pre></div><p>Or copy <code>skills/laravel-myanmar-nrc</code> from the <a href="https://github.com/laranex/laravel-myanmar-nrc" target="_blank" rel="noreferrer">repository</a> into your project&#39;s <code>.claude/skills</code> or <code>.agents/skills</code> folder.</p><h2 id="what-the-skill-covers" tabindex="-1">What the skill covers <a class="header-anchor" href="#what-the-skill-covers" aria-label="Permalink to &quot;What the skill covers&quot;">​</a></h2><p>Validate Myanmar NRC numbers and format them in English or Myanmar in a Laravel app with laranex/laravel-myanmar-nrc, reading the bundled state, township and type data from the database or the JSON file.</p><p>It is written from the package source and kept in the repository next to the code, so agents follow the same API, configuration and conventions these docs describe.</p><h2 id="keeping-it-current" tabindex="-1">Keeping it current <a class="header-anchor" href="#keeping-it-current" aria-label="Permalink to &quot;Keeping it current&quot;">​</a></h2><p>The skill lives in the package repository and is versioned with it, so it always describes the release you install. When you update Laravel Myanmar NRC, update the skill the same way you installed it.</p>',14)])])}const u=e(r,[["render",n]]);export{k as __pageData,u as default};
